"""Render the Homebrew formula for the lineup CLI.

    python3 render-formula.py VERSION BASE_URL SHA256SUMS OUT

VERSION is the release version without the leading v (0.7.0). BASE_URL is where the archives
live: the release download URL, or a file:// URL for testing. SHA256SUMS is the release's
`<sha256>  <archive>` list. The formula installs the client-only `lineup-cli-*` build (no server,
no web UI) for Apple Silicon and 64-bit Linux, as `lineup`.
"""

import pathlib
import re
import sys

HOMEPAGE = "https://github.com/alexey-lapin/lineup"
DESCRIPTION = "CLI for lineup, an IPTV channel, M3U playlist and XMLTV guide manager"
TARGETS = {
    "darwin_arm": "aarch64-apple-darwin",
    "linux_x86": "x86_64-unknown-linux-gnu",
    "linux_arm": "aarch64-unknown-linux-gnu",
}


def main(version, base_url, checksums, out):
    if not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", version):
        raise SystemExit(f"{version!r} is not a stable X.Y.Z version")
    sums = {}
    for line in pathlib.Path(checksums).read_text().splitlines():
        digest, name = line.split()
        name = name.lstrip("*")
        if name in sums:
            raise SystemExit(f"{name} is listed twice in {checksums}")
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise SystemExit(f"{name}: {digest!r} is not a sha256")
        sums[name] = digest

    def archive(key):
        name = f"lineup-cli-v{version}-{TARGETS[key]}.tar.gz"
        if name not in sums:
            raise SystemExit(f"{name} is not in {checksums}")
        return f"{base_url.rstrip('/')}/{name}", sums[name]

    a = {k: archive(k) for k in TARGETS}
    formula = f'''# typed: false
# frozen_string_literal: true

# Generated by .github/scripts/render-formula.py in alexey-lapin/lineup. Do not edit.
class Lineup < Formula
  desc "{DESCRIPTION}"
  homepage "{HOMEPAGE}"
  version "{version}"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "{a["darwin_arm"][0]}"
      sha256 "{a["darwin_arm"][1]}"
    end
  end

  on_linux do
    if Hardware::CPU.intel? && Hardware::CPU.is_64_bit?
      url "{a["linux_x86"][0]}"
      sha256 "{a["linux_x86"][1]}"
    end
    if Hardware::CPU.arm? && Hardware::CPU.is_64_bit?
      url "{a["linux_arm"][0]}"
      sha256 "{a["linux_arm"][1]}"
    end
  end

  def install
    bin.install "lineup"
    generate_completions_from_executable(bin/"lineup", "completions")
  end

  test do
    assert_match "lineup {version}", shell_output("#{{bin}}/lineup --version")
    # The client-only build: no server inside.
    assert_match "unrecognized subcommand", shell_output("#{{bin}}/lineup serve 2>&1", 2)
  end
end
'''
    pathlib.Path(out).write_text(formula)


if __name__ == "__main__":
    if len(sys.argv) != 5:
        raise SystemExit(__doc__)
    main(*sys.argv[1:])
